import json,re,functools
T=json.load(open('tasks.json')); G=json.load(open('gen.json'))
merged={'T-008','T-012','T-013','T-014','T-016','T-017','T-018','T-019','T-024','T-026'}
H={}
for k,v in T.items():
    head=v['deps_head'].split('**',2)[-1].strip().lower() if '**' in v['deps_head'] else ''
    H[k]=set() if head.startswith('none') else set(v['deps'])-{x for x in v['deps'] if False}
    H[k]-= {'T-028'} if k=='T-026' else set()
open_={k for k in T if k not in merged}
for k in open_:
    mine=H[k]-merged; gen=set(G[k]['hard'])
    if mine!=gen: print('DIFF',k,'mine',sorted(mine),'gen',sorted(gen))
# cycles & depth
@functools.lru_cache(None)
def d(t,stack=()):
    if t in stack: raise SystemExit('cycle '+str(stack+(t,)))
    return 1+max([d(x,stack+(t,)) for x in H[t] if x in open_] or [0])
B={k:d(k) for k in open_}
bad=[k for k in open_ if B[k]!=G[k]['batch']]; print('batch mismatches',bad)
import collections; print(sorted(collections.Counter(B.values()).items()))
# all longest paths
def paths(t):
    ps=[p+[t] for x in H[t] if x in open_ for p in paths(x)]
    return ps or [[t]]
L=max(B.values()); allp=[p for k in open_ if B[k]==L for p in paths(k) if len(p)==L]
print('longest len',L); [print(' -> '.join(p)) for p in allp]
# missing deps
print('missing',sorted({x for k in T for x in H[k] if x not in T}))
# research before tooling: research task R and tooling task X with X reachable after R where... list research tasks with descendants that are tooling
desc=collections.defaultdict(set)
for k in open_:
    for x in H[k]:
        if x in open_: desc[x].add(k)
for k in sorted(open_):
    if G[k]['kind']=='RESEARCH':
        tooling_after=[x for x in desc[k] if G[x]['kind']=='TOOLING']
        if tooling_after: print('research',k,'is prerequisite of tooling',tooling_after)
EOF

